#1587;&#1605;&#1576;&#1604;&#1740; &#1705;&#1746; &#1585;&#1606; &#1576;&#1606;&#1746; &#1575;&#1608;&#1585; &#1575;&#1587; &#1705;&#1746; &#1576;&#1593;&#1583; &#1608;&#1601;&#1575; &#1602;&#1740; &#1608;&#1586;&#1740;&#1585; &#1576;&#1585;&#1575; &#1574;&#1746; &#1585;&#1740;&#1604;&#1608; &#1746; &#1705;&#1575; &#1602;&#1604;&#1605; &#1583;&#1575; &#1606; &#1575;&#1606; &#1705;&#1746; &#1587;&#1662;&#1585; &#1583; &#1705;&#1740;&#1575;&#1711;&#1740;&#1575; &#1748; &#1608;&#1729; &#1662;&#1575; &#1705;&#1587;&#1578;&#1575; &#1606; &#1662;&#1740;&#1662;&#1604;&#1586; &#1662;&#1575; &#1585;&#1657;&#1740; &#1705;&#1746; &#1606;&#1592;&#1585; &#1740;&#1575; &#1578;&#1740; &#1548; &#1576;&#1575; &#1575;&#1589;&#1608;&#1604; &#1548; &#1575;&#1740;&#1605;&#1575; &#1606; &#1583;&#1575; &#1585;&#1548; &#1588;&#1601;&#1575; &#1601; &#1575;&#1608;&#1585; &#1575;&#1606;&#1602;&#1604;&#1575; &#1576;&#1740; &#1585;&#1729;&#1606;&#1605;&#1575; &#1574;&#1608;&#1722; &#1605;&#1740;&#1722; &#1588;&#1605;&#1575; &#1585; &#1729;&#1608; &#1578;&#1746; &#1729;&#1740;&#1722; &#1575;&#1606; &#1705;&#1746; &#1575;&#1606;&#1729;&#1740; &#1662;&#1729;&#1604;&#1608;&#1574;&#1608;&#1722; &#1705;&#1608; &#1605;&#1583; &#1606;&#1592;&#1585; &#1585;&#1705;&#1726; &#1705;&#1585; &#1584;&#1608;&#1575;&#1604;&#1601;&#1602;&#1575; &#1585; &#1593;&#1604;&#1740; &#1576;&#1726;&#1657;&#1608; &#1606;&#1746; &#1575;&#1606; &#1705;&#1608; 1977 &#1605;&#1740;&#1722; &#1662;&#1575; &#1705;&#1587;&#1578;&#1575; &#1606; &#1662;&#1740;&#1662;&#1604;&#1586; &#1662;&#1575; &#1585; &#1657;&#1740; &#1705;&#1575; &#1587;&#1740;&#1705;&#1585;&#1657;&#1585; &#1740; &#1580;&#1606;&#1585; &#1604; &#1576;&#1606;&#1575; &#1740;&#1575; &#1575;&#1608;&#1585; &#1575;&#1587; &#1584;&#1605;&#1729; &#1583;&#1575; &#1585; &#1740; &#1705;&#1608; &#1608;&#1729; 1985 &#1578;&#1705; &#1606;&#1576;&#1726;&#1575; &#1578;&#1746; &#1585;&#1729;&#1746; &#1548; &#1601;&#1585; &#1608; &#1585; &#1740; 1974 &#1705;&#1608; &#1604;&#1575; &#1