INSERT INTO `news` VALUES (138,'Lahore\'s Moti Masjid is the earliest of three Mughal \'Pearl Mosques.\' (By Shahbaz Aslam)','<p>\r\n	Lahore&#39;s Moti Masjid is the earliest of three Mughal &#39;Pearl Mosques.&#39; The two others are the one in Agra and the other in Delhi. (By Shahbaz Aslam)</p>\r\n','Lahore Fort','news/small_138.jpg','news/orgsize_138LahoreFort6.jpg',1,''),(137,'Alamgiri Gate is the entrance of the Lahore Fort. It was built by the Mughal emperor Aurangzeb in 1674. (By King Eliot)','<p>\r\n	Alamgiri Gate is the entrance of the Lahore Fort. It was built by the Mughal emperor Aurangzeb in 1674. (By King Eliot)</p>\r\n','Lahore Fort','news/small_137.jpg','news/orgsize_137LahoreFort5.jpg',1,''),(132,'View of the Alamgiri Gate of the \'The Lahore Fort\' (Shahi Qilah) is a citadel of Lahore, Pakistan. (By Rohaan Bhatti)','<p>\r\n	View of the Alamgiri Gate of the &#39;The Lahore Fort&#39; (Shahi Qilah) is a citadel of Lahore, Pakistan. (By Rohaan Bhatti)</p>\r\n','Lahore Fort','news/small_132.jpg','news/orgsize_132LahoreFort.jpg',1,''),(133,'The marble Naulakha Pavilion is one of the most iconic sights at the fort. By Jawad Hassan 89','<p>\r\n	The marble Naulakha Pavilion is one of the most iconic sights at the fort. By Jawad Hassan 89</p>\r\n','Lahore Fort','news/small_133.jpg','news/orgsize_133LahoreFort1.jpg',1,''),(134,'The Sheesh Mahal is elaborately decorated with a myriad of reflective glass tiles. By Faisalrazamalik ','<p>\r\n	The Sheesh Mahal is elaborately decorated with a myriad of reflective glass tiles. By Faisalrazamalik&nbsp;</p>\r\n','Lahore Fort','news/small_134.jpg','news/orgsize_134LahoreFort2.jpg',1,''),(135,'The Summer Palace is a labyrinth of chambers that was used as a residence during the hot summer months. (Walled City of Lahore Authority)','<p>\r\n	The Summer Palace is a labyrinth of chambers that was used as a residence during the hot summer months. (The Walled City of Lahore Authority - Saqib received this file by e-mail from the Walled City of Lahore Authority)</p>\r\n','Lahore Fort','news/small_135.jpg','news/orgsize_135LahoreFort3.jpg',1,''),(136,'The Diwan-i-Khas is where the Emperor would attend to state affairs. (By Muhammad Ashar)','<p>\r\n	The Diwan-i-Khas is where the Emperor would attend to state affairs.&nbsp;(By Muhammad Ashar)</p>\r\n','Lahore Fort','news/small_136.jpg','news/orgsize_136LahoreFort4.jpg',1,'');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

