INSERT INTO `news_body` VALUES (3,'Why should you be a part of PrideofPakistan?','<center>\r\n	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"100%\" id=\"backgroundTable\" style=\"background:#082600;\" width=\"100%\">\r\n		<tbody>\r\n			<tr>\r\n				<td>\r\n					<p>\r\n						&nbsp;</p>\r\n				</td>\r\n			</tr>\r\n			<tr>\r\n				<td align=\"center\" valign=\"top\">\r\n					<table bgcolor=\"#FFFFFF\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" id=\"templateContainer\" style=\"border:1px solid #eaeaea;\" width=\"550\">\r\n						<tbody>\r\n							<tr>\r\n								<td align=\"center\" valign=\"top\">\r\n									<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"headerContent\" id=\"templateHeader\" style=\"\r\nborder-bottom: 1px solid #666666;\r\ncolor: #FFFFFF;\r\nfont-family: Arial;\r\nfont-size: 14px;\r\nfont-weight: bold;\r\nline-height: normal;\r\npadding: 10px;\r\ntext-align: left;\r\nvertical-align: middle;\" width=\"550\">\r\n										<tbody>\r\n											<tr>\r\n												<td width=\"250\">\r\n													<span style=\"font-family:tahoma,geneva,sans-serif;\"><img border=\"0\" src=\"https://www.prideofpakistan.com/images/logo.png\" style=\"height:65px; float: left;\" /></span></td>\r\n												<td width=\"295\">\r\n													&nbsp;</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n								</td>\r\n							</tr>\r\n							<tr>\r\n								<td align=\"center\" valign=\"top\">\r\n									<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" id=\"templateBody\" width=\"550\">\r\n										<tbody>\r\n											<tr>\r\n												<td class=\"bodyContent\" style=\"padding: 0px 14px; line-height: 1.3em;\" valign=\"top\">\r\n													<p style=\"text-align: justify;\">\r\n														<br />\r\n														<span style=\"color:#808080;\"><span style=\"font-family:tahoma,geneva,sans-serif;\"><span style=\"font-size:14px;\"><strong>PrideofPakistan.com</strong><strong> </strong>website is dedicated to highlight and recognize the diverse range of abilities and characters of good, law abiding, talented and hardworking individuals who have taken what it means to be a Pakistani. Individuals and organizations alike are welcomed to try Pride of Pakistan website </span></span></span><span style=\"font-family:tahoma,geneva,sans-serif;\"><span style=\"font-size:14px;\"><a href=\"https://www.prideofpakistan.com/\"><span style=\"color:#808080;\">PrideofPakistan.com</span></a></span></span><span style=\"color:#808080;\"><span style=\"font-family:tahoma,geneva,sans-serif;\"><span style=\"font-size:14px;\"> for a variety of uses.</span></span></span></p>\r\n													<p style=\"text-align: justify;\">\r\n														<span style=\"color:#808080;\"><span style=\"font-size:14px;\"><span style=\"font-family:tahoma,geneva,sans-serif;\">This is an exciting project, which will provide a positive look at our culture and our people. Your contribution and participation would help build this into a centre of excellence reflecting the best of Pakistan.</span></span></span></p>\r\n													<p style=\"text-align: justify;\">\r\n														<span style=\"color:#808080;\"><span style=\"font-size:14px;\"><span style=\"font-family:tahoma,geneva,sans-serif;\">Best Regards,</span></span></span></p>\r\n													<p style=\"text-align: justify;\">\r\n														<span style=\"color:#808080;\"><span style=\"font-size:14px;\"><span style=\"font-family:tahoma,geneva,sans-serif;\">PrideofPakistan Team</span></span></span></p>\r\n													<table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n													</table>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td bgcolor=\"#E9E7E5\" style=\"background:#E9E7E5;\">\r\n													<table align=\"center\" bgcolor=\"#E9E7E5\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#E9E7E5; padding:0px 20px;\">\r\n														<tbody>\r\n															<tr>\r\n																<td colspan=\"3\">\r\n																	&nbsp;</td>\r\n															</tr>\r\n															<tr>\r\n																<td align=\"center\" colspan=\"3\" style=\"color: #333;\r\nfont-family: Arial, Helvetica, sans-serif;\r\nfont-size: 12px;\r\nmargin: 10px 0px 0px 0px;\r\nfloat:left;\r\nline-height: 19px;\r\n\">\r\n																	<span style=\"font-family:tahoma,geneva,sans-serif;\">&copy; Copyright 2020 Pride of Pakistan All right reserved.</span></td>\r\n															</tr>\r\n														</tbody>\r\n													</table>\r\n												</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n								</td>\r\n							</tr>\r\n						</tbody>\r\n					</table>\r\n					<p>\r\n						&nbsp;</p>\r\n				</td>\r\n			</tr>\r\n		</tbody>\r\n	</table>\r\n</center>\r\n<p>\r\n	&nbsp;</p>\r\n','','6895','2020-06-19 11:05:01',2);
/*!40000 ALTER TABLE `news_body` ENABLE KEYS */;
UNLOCK TABLES;

